        /// <summary>
        /// Delete transaction(statement)
        /// </summary>
        /// Phuong.Nguyen updated
        /// <param name="refNo"></param>
        /// <param name="custId"></param>
        /// <param name="userId"></param>
        public static IbcError Acc_BettransDelTransaction(long refNo, int custId, int userId, string ip, bool isReward)
        {
            var resultTuple = GetCustIdsByRefNo(refNo);
            var result = resultTuple.Item2;

            return result.ErrorCode != 0
                ? result
                : Acc_BettransDelTransaction(refNo, custId, userId, ip, resultTuple.Item1, isReward);
        }

        private static Tuple<IEnumerable<int>, IbcError> GetCustIdsByRefNo(long refNo)
        {
            IbcError result;
            IList<int> custIds = new List<int>();
            var inputParams = new Hashtable
            {
                ["refno"] = refNo,
                ["errcode"] = 0,
                ["errmsg"] = string.Empty
            };

            try
            {
                using (var db = new ObjectDb("Acc_CustomerSelByRefno"))
                {
                    using (var reader = db.ExecuteReader(inputParams))
                    {
                        while (reader.Read())
                        {
                            custIds.Add(Convert.ToInt32(reader["custid"]));
                        }
                    }

                    var outputParams = db.GetOuputParams();
                    result = new IbcError(Convert.ToInt32(outputParams["errcode"]), outputParams["errmsg"].ToString());
                }
            }
            catch (Exception ex)
            {
                result = new IbcError(500, ex.Message);
                LogExtensions.Error(string.Empty, "Acc_CustomerSelByRefno", inputParams, ex);
            }

            return Tuple.Create<IEnumerable<int>, IbcError>(custIds, result);
        }

        private static IbcError Acc_BettransDelTransaction(long refNo, int custId, int userId, string ip, IEnumerable<int> custIds, bool isReward)
        {
            IbcError result = null;
            IEnumerable<SiteDB> rollbackSiteDBList = Enumerable.Empty<SiteDB>();
            var uniqueSiteDBArray = GetUniqueSiteDBFromCustIds(custIds);

            for (int i = 0, max = uniqueSiteDBArray.Length; i < max; i++)
            {
                var siteDB = uniqueSiteDBArray[i];
                result = Acc_BettransDelTransaction(refNo, custId, userId, ip, siteDB);

                if (result.ErrorCode != 0)
                {
                    if (i > 0)
                    {
                        rollbackSiteDBList = uniqueSiteDBArray.Take(i).ToList();
                    }

                    break;
                }
            }

            if (rollbackSiteDBList.Any())
            {
                SiteDB_Acc_ReverseTransfer_Rollback(refNo, userId, ip, rollbackSiteDBList);
            }

            return result ?? new IbcError();
        }

        private static SiteDB[] GetUniqueSiteDBFromCustIds(IEnumerable<int> custIds)
        {
            IDictionary<int, SiteDB> siteDBDict = new Dictionary<int, SiteDB>();

            foreach (var custId in custIds)
            {
                var siteDB = ObjectDbExtensions.GetSiteDBConfigByCustId(custId);

                if (!siteDBDict.ContainsKey(siteDB.SiteDBGroupID))
                {
                    siteDBDict.Add(siteDB.SiteDBGroupID, siteDB);
                }
            }

            return siteDBDict.Values.ToArray();
        }

        private static IbcError Acc_BettransDelTransaction(long refNo, int custId, int userId, string ip, SiteDB siteDB)
        {
            var settingKey = siteDB.IsSiteDB
                ? $"SiteDB{siteDB.SiteDBGroupID}_Acc_BettransDelTransaction"
                : "Acc_BettransDelTransaction";
            var inputParams = new Hashtable
            {
                ["refno"] = refNo,
                ["custid"] = custId,
                ["userid"] = userId,
                ["ip"] = ip,
                ["sitedbgroupid"] = siteDB.SiteDBGroupID,
                ["errcode"] = 0,
                ["errmsg"] = string.Empty
            };

            try
            {
                using (var db = new ObjectDb(settingKey, 1200))
                {
                    db.ExecuteNonQueryScaleoutDB(inputParams, siteDB.AGIP);

                    return new IbcError(
                        DNAide.Core.CastAide.AsInt32(db.GetParameterValue("errcode")),
                        string.Format("{0}", db.GetParameterValue("errmsg")));
                }
            }
            catch (Exception ex)
            {
                Sunplus.Accounting.Core.Extensions.LogExtensions.Error(
                    siteDB.AGIP,
                    settingKey,
                    inputParams,
                    ex);
                return new IbcError(100, ex.Message);
            }
        }

        private static void SiteDB_Acc_ReverseTransfer_Rollback(long refNo, int userId, string ip, IEnumerable<SiteDB> siteDBList)
        {
            foreach (var siteDB in siteDBList)
            {
                SiteDB_Acc_ReverseTransfer_Rollback(refNo, userId, ip, siteDB);
            }
        }

        private static IbcError SiteDB_Acc_ReverseTransfer_Rollback(long refNo, int userId, string ip, SiteDB siteDB)
        {
            var settingKey = siteDB.IsSiteDB
                ? $"SiteDB{siteDB.SiteDBGroupID}_SiteDB_Acc_ReverseTransfer_Rollback"
                : "SiteDB_Acc_ReverseTransfer_Rollback";
            var inputParams = new Hashtable
            {
                ["refno"] = refNo,
                ["userid"] = userId,
                ["ip"] = ip,
                ["sitedbgroupid"] = siteDB.SiteDBGroupID,
                ["errcode"] = 0,
                ["errmsg"] = string.Empty
            };

            try
            {
                using (var db = new ObjectDb(settingKey, 1200))
                {
                    db.ExecuteNonQueryScaleoutDB(inputParams, siteDB.AGIP);

                    return new IbcError(
                        DNAide.Core.CastAide.AsInt32(db.GetParameterValue("errcode")),
                        string.Format("{0}", db.GetParameterValue("errmsg")));
                }
            }
            catch (Exception ex)
            {
                Sunplus.Accounting.Core.Extensions.LogExtensions.Error(
                    siteDB.AGIP,
                    settingKey,
                    inputParams,
                    ex);
                return new IbcError(100, ex.Message);
            }
        }

